import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BQq6mqvm.js";const c=JSON.parse('{"title":"这是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is.md","filePath":"guide/what-is.md","lastUpdated":1790385461000}'),i={name:"guide/what-is.md"};function o(l,t,s,n,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h1><p>局域网文件助手是一个可以部署在自己服务器上的文件共享网盘，用来在团队或公司内部共享文件。</p><p>它解决的核心问题是：<strong>文件需要让所有人看到，但只能由上传者自己改动。</strong></p><h2 id="与传统共享文件夹的区别" tabindex="-1">与传统共享文件夹的区别 <a class="header-anchor" href="#与传统共享文件夹的区别" aria-label="Permalink to &quot;与传统共享文件夹的区别&quot;">​</a></h2><p>传统的共享文件夹（如 Windows 共享盘、NAS）通常只有两种做法：要么所有人都能改，要么需要逐个目录分配权限。前者容易误删、误改；后者维护起来很麻烦。</p><p>局域网文件助手把「归属」和「可见性」分开：</p><ul><li><strong>归属</strong>：每个文件都有明确的上传者，只有上传者本人（和管理员）能改名或删除。</li><li><strong>可见性</strong>：所有登录用户都能浏览、搜索、下载、预览所有人的文件。</li></ul><p>所以每个人都有一个属于自己的目录，同时所有人都能看见这些目录里的内容。</p><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>工号登录</td><td>用姓名 + 工号 + 密码登录，账号由管理员创建</td></tr><tr><td>独立目录</td><td>每位成员一个目录，只能修改自己的文件</td></tr><tr><td>全员可读</td><td>浏览、搜索、下载、预览任意成员的文件</td></tr><tr><td>在线预览</td><td>常见办公文档与媒体文件无需下载即可查看</td></tr><tr><td>大文件上传</td><td>分片上传，支持断点续传</td></tr><tr><td>自动清理</td><td>文件到期自动删除，回收站可恢复</td></tr><tr><td>管理后台</td><td>用户、容量、类型、日志统一管理</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想先了解能做什么 → <a href="./features">功能一览</a></li><li>想把它跑起来 → <a href="./deploy">部署</a></li><li>已经部署好了，想学怎么用 → <a href="./../usage/login">使用教程</a></li></ul>',12)])])}const _=a(i,[["render",o]]);export{c as __pageData,_ as default};
